-- A20: independently sealed absence, explicit retry, original TOP_UP.
CREATE TABLE d4.absence_seals(id uuid PRIMARY KEY,proof_id uuid NOT NULL UNIQUE REFERENCES d4.recovery_proofs(id),delivery_id uuid NOT NULL REFERENCES d4.deliveries(id),operation_id uuid NOT NULL REFERENCES public.operations(id),generation bigint NOT NULL,attempt_id uuid NOT NULL REFERENCES public.execution_attempts(id),reservation_id uuid NOT NULL REFERENCES d2.reservations(id),committed_version bigint NOT NULL,UNIQUE(operation_id,generation));
CREATE TABLE d4.absence_authorizations(id uuid PRIMARY KEY,seal_id uuid NOT NULL REFERENCES d4.absence_seals(id),authorized_version bigint NOT NULL,reason text NOT NULL);
CREATE TABLE d4.absence_links(seal_id uuid PRIMARY KEY REFERENCES d4.absence_seals(id),authorization_id uuid NOT NULL REFERENCES d4.absence_authorizations(id),attempt_id uuid NOT NULL UNIQUE REFERENCES public.execution_attempts(id),generation bigint NOT NULL);

DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['absence_seals','absence_authorizations','absence_links'] LOOP EXECUTE format('CREATE TRIGGER immutable_fact BEFORE UPDATE OR DELETE OR TRUNCATE ON d4.%I FOR EACH STATEMENT EXECUTE FUNCTION public.d2_reject_fact_mutation()',t);END LOOP;END $$;

CREATE FUNCTION d4.absence_safe(oid uuid,gen bigint) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,d4 AS $$
 SELECT EXISTS(SELECT 1 FROM d4.absence_seals s JOIN d4.absence_authorizations a ON a.seal_id=s.id JOIN public.operations o ON o.id=s.operation_id WHERE s.operation_id=oid AND s.generation=gen AND o.lease_generation=gen AND o.state='READY' AND o.row_version=a.authorized_version AND d4.recovery_current(s.id) AND NOT EXISTS(SELECT 1 FROM d4.absence_links WHERE seal_id=s.id));
$$;

CREATE FUNCTION d4.absence_authorize(cid uuid,seal uuid,expected_version bigint,reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,d2,d3,d4 AS $$
DECLARE req jsonb=jsonb_build_object('action','ABSENCE_AUTHORIZE','seal',seal,'version',expected_version,'reason',reason);prior jsonb;s d4.absence_seals;o public.operations;result jsonb;
BEGIN
 PERFORM d3.lock_state();prior=d4.checkpoint_previous(cid,req);IF prior IS NOT NULL THEN RETURN prior;END IF;SELECT * INTO STRICT s FROM d4.absence_seals WHERE id=seal;SELECT * INTO STRICT o FROM public.operations WHERE id=s.operation_id;
 IF o.state NOT IN ('RETRY_PENDING','READY') OR o.row_version IS DISTINCT FROM expected_version OR o.lease_generation<>s.generation OR NOT d4.recovery_current(s.id) OR EXISTS(SELECT 1 FROM d4.absence_links WHERE seal_id=seal) OR (SELECT count(*) FROM public.execution_attempts WHERE operation_id=o.id)>=coalesce((o.policy_snapshot->>'max_attempts')::int,3) OR reason IS NULL OR length(btrim(reason)) NOT BETWEEN 1 AND 512 THEN RAISE EXCEPTION 'Current unused absence, authorization and budget required' USING ERRCODE='23514';END IF;
 UPDATE public.operations SET state='READY',row_version=row_version+1 WHERE id=o.id;IF o.state<>'READY' THEN PERFORM d2.record_transition(cid,'OPERATION',o.id,o.state,'READY',o.row_version+1,'CONTROL_PLANE','Explicit absence retry');END IF;
 INSERT INTO d4.absence_authorizations VALUES(cid,seal,o.row_version+1,reason);result=jsonb_build_object('state','READY','row_version',o.row_version+1);INSERT INTO d4.checkpoint_commands VALUES(cid,req,result);RETURN result;
END $$;

CREATE FUNCTION d4.parent_linked(oid uuid,parent uuid,attempt uuid,gen bigint) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,d4 AS $$
 WITH RECURSIVE lineage(a,g) AS(SELECT attempt,gen UNION ALL SELECT s.attempt_id,s.generation FROM lineage x JOIN d4.absence_links l ON l.attempt_id=x.a AND l.generation=x.g JOIN d4.absence_seals s ON s.id=l.seal_id WHERE s.operation_id=oid AND s.generation+1=x.g)
 SELECT CASE WHEN parent IS NULL THEN EXISTS(SELECT 1 FROM lineage x JOIN public.execution_attempts a ON a.id=x.a WHERE a.operation_id=oid AND a.attempt_no=1 AND x.g=1) ELSE EXISTS(SELECT 1 FROM lineage x JOIN d4.multi_links l ON l.attempt_id=x.a AND l.generation=x.g JOIN d4.multi_checkpoints cp ON cp.id=l.checkpoint_id WHERE cp.id=parent AND cp.operation_id=oid AND cp.source_generation+1=x.g) END;
$$;

ALTER FUNCTION d4.continuation_safe(uuid,bigint) RENAME TO continuation_safe_before_absence;
CREATE FUNCTION d4.continuation_safe(oid uuid,gen bigint) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,d4 AS $$ SELECT d4.continuation_safe_before_absence(oid,gen) OR d4.absence_safe(oid,gen); $$;
ALTER VIEW d4.continuation_admissions RENAME TO checkpoint_admissions_before_absence;
CREATE VIEW d4.continuation_admissions AS SELECT * FROM d4.checkpoint_admissions_before_absence UNION ALL SELECT s.operation_id,s.generation,s.id,a.id,p.proof->>'recovery_manifest_hash','SEALED_ABSENCE',d4.absence_safe(s.operation_id,s.generation) AND a.authorized_version=(SELECT row_version FROM public.operations WHERE id=s.operation_id) FROM d4.absence_seals s JOIN d4.absence_authorizations a ON a.seal_id=s.id JOIN d4.recovery_proofs p ON p.id=s.proof_id;
ALTER FUNCTION d3.state_relations() RENAME TO state_relations_before_absence;
CREATE FUNCTION d3.state_relations() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT d3.state_relations_before_absence()||ARRAY['d4.absence_seals','d4.absence_authorizations','d4.absence_links']; $$;
CREATE FUNCTION d4.absence_audit() RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public,d4 AS $$ SELECT d4.recovery_audit()||jsonb_build_object('absence_seals',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM d4.absence_seals t),'absence_authorizations',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM d4.absence_authorizations t),'absence_links',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM d4.absence_links t)); $$;

CREATE FUNCTION d4.absence_info(delivery uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public,d4 AS $$ SELECT d4.recovery_info(delivery); $$;
-- Only durable seals and authorized CLAIM links may explain intermediate attempts.
CREATE FUNCTION d4.absence_lineage(delivery uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,d2,d3,d4 AS $$
 WITH RECURSIVE chain(a,g) AS (
 SELECT ds.attempt_id,ds.generation FROM d4.deliveries d JOIN d3.dispatches ds ON ds.command_id=d.dispatch_command_id WHERE d.id=delivery
 UNION ALL SELECT s.attempt_id,s.generation FROM chain x JOIN d4.absence_links l ON l.attempt_id=x.a AND l.generation=x.g JOIN d4.absence_seals s ON s.id=l.seal_id WHERE s.generation+1=x.g),
 links AS(SELECT s.generation,p.proof source,d4.recovery_info(d.id) target,sa.attempt_no source_count,ta.attempt_no target_count,encode(public.digest(p.proof::text,'sha256'),'hex') seal_hash,d4.recovery_current(s.id) current
 FROM chain x JOIN d4.absence_links l ON l.attempt_id=x.a AND l.generation=x.g JOIN d4.absence_seals s ON s.id=l.seal_id JOIN d4.recovery_proofs p ON p.id=s.proof_id JOIN public.execution_attempts sa ON sa.id=s.attempt_id JOIN public.execution_attempts ta ON ta.id=l.attempt_id JOIN d3.dispatches ds ON ds.attempt_id=l.attempt_id JOIN d4.deliveries d ON d.dispatch_command_id=ds.command_id)
 SELECT coalesce(jsonb_agg(jsonb_build_object('source',source,'target',target,'source_count',source_count,'target_count',target_count,'seal_hash',seal_hash,'current',current) ORDER BY generation),'[]') FROM links;
$$;


CREATE OR REPLACE FUNCTION d4.recovery_evaluate(delivery uuid,proof jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,d2,d3,d4 AS $$
DECLARE i jsonb=d4.recovery_info(delivery);m jsonb=i->'recovery_manifest';o public.operations;res d2.reservations;parent jsonb=coalesce(i->'parent_evaluation','{}');applied jsonb=coalesce(parent->'applied','{}');remaining boolean=false;progress int=0;s jsonb;r jsonb;e record;a record;cost numeric;delta numeric;prev numeric;consumes jsonb='{}';releases jsonb='{}';cumulative jsonb='{}';terminal boolean;allowed jsonb;expected_key text;
BEGIN
 SELECT * INTO STRICT o FROM public.operations WHERE id=(i->>'operation')::uuid;SELECT * INTO STRICT res FROM d2.reservations WHERE operation_id=o.id;
 IF o.state NOT IN ('RECONCILING','BLOCKED_APPROVAL') OR (i->>'lease_expired')::boolean IS DISTINCT FROM true
 OR NOT EXISTS(SELECT 1 FROM public.operation_leases l WHERE l.operation_id=o.id AND l.attempt_id=(i->>'attempt')::uuid AND l.worker_id=(i->>'worker')::uuid AND l.fencing_generation=o.lease_generation AND o.lease_generation=(i->>'generation')::bigint)
 OR proof->>'schema' IS DISTINCT FROM 'd4.recovery.proof.v1' OR proof->>'recovery_manifest_hash' IS DISTINCT FROM i->>'recovery_manifest_hash'
 OR proof->'receipt_basis' IS DISTINCT FROM i->'receipt_basis' OR proof->>'context_hash' IS DISTINCT FROM o.context_pack_sha256 OR proof->>'policy_hash' IS DISTINCT FROM encode(public.digest(o.policy_snapshot::text,'sha256'),'hex')
 OR EXISTS(SELECT 1 FROM jsonb_each(jsonb_build_object('operation',i->'operation','attempt',i->'attempt','worker',i->'worker','resource',i->'resource','generation',i->'generation')) x WHERE proof->x.key IS DISTINCT FROM x.value)
 OR proof->'process_stopped' IS DISTINCT FROM 'true'::jsonb OR proof->'artifact_valid' IS DISTINCT FROM 'true'::jsonb OR proof->'receiver_closed' IS DISTINCT FROM 'true'::jsonb
 OR coalesce(proof->>'host_observation_hash','') !~ '^[a-f0-9]{64}$' OR coalesce(proof->>'stdout_hash','') !~ '^[a-f0-9]{64}$' OR coalesce(proof->>'stderr_hash','') !~ '^[a-f0-9]{64}$'
 OR jsonb_typeof(proof->'receipts') IS DISTINCT FROM 'object' OR coalesce((proof->>'close_sequence')::bigint,0)<=0
 OR NOT EXISTS(SELECT 1 FROM d4.lab_grants g WHERE g.request->>'delivery'=delivery::text AND g.response->>'receiver_id'=proof->'receiver_seal'->>'receiverId')
 OR proof->'receiver_seal'->'steps' IS DISTINCT FROM proof->'receipts' OR proof->'receiver_seal'->'sequence' IS DISTINCT FROM proof->'close_sequence'
 OR EXISTS(SELECT 1 FROM jsonb_each(jsonb_build_object('operation',i->'operation','attempt',i->'attempt','worker',i->'worker','resource',i->'resource','generation',i->'generation')) x WHERE proof->'receiver_seal'->'identity'->x.key IS DISTINCT FROM x.value)
 OR (i->'multi_checkpoint'='true'::jsonb AND proof->'parent_checkpoint' IS DISTINCT FROM i->'parent_checkpoint')
 OR (i->'multi_checkpoint'='true'::jsonb AND NOT d4.parent_linked(o.id,(i->>'parent_checkpoint')::uuid,(i->>'attempt')::uuid,o.lease_generation))
 OR res.resource_id IS DISTINCT FROM (m->>'resource')::uuid OR res.pool IS DISTINCT FROM m->>'pool'
 THEN RAISE EXCEPTION 'Exact independently stopped sealed recovery required' USING ERRCODE='23514';END IF;
 -- Prior-generation evidence must remain explained by native checkpoints/resolutions.
 IF EXISTS(SELECT 1 FROM d2.effect_receipts er WHERE er.operation_id=o.id AND er.generation<>o.lease_generation AND NOT d4.receipt_resolved(er.id) AND NOT EXISTS(
 SELECT 1 FROM d4.multi_checkpoints cp JOIN d4.multi_proofs pr ON pr.id=cp.proof_id CROSS JOIN LATERAL jsonb_each(pr.proof->'receipts') rr WHERE cp.operation_id=o.id AND cp.source_generation=er.generation AND er.effect_key=o.id||'/'||o.context_pack_sha256||'/'||rr.key AND er.status=rr.value->>'status') AND NOT EXISTS(
 SELECT 1 FROM d4.checkpoints cp WHERE cp.operation_id=o.id AND cp.source_generation=er.generation AND ((er.effect_key=o.id||'/'||o.context_pack_sha256||'/step-1' AND er.status='APPLIED') OR (er.effect_key=o.id||'/'||o.context_pack_sha256||'/step-2' AND er.status='ABSENT')))) THEN RAISE EXCEPTION 'Prior evidence unresolved' USING ERRCODE='23514';END IF;
 SELECT coalesce(jsonb_agg(value->>'id' ORDER BY n),'[]') INTO allowed FROM jsonb_array_elements(m->'steps') WITH ORDINALITY x(value,n) WHERE NOT applied ? (value->>'id');
 IF (SELECT array_agg(key ORDER BY key) FROM jsonb_each(proof->'receipts')) IS DISTINCT FROM (SELECT array_agg(value#>>'{}' ORDER BY value#>>'{}') FROM jsonb_array_elements(allowed)) THEN RAISE EXCEPTION 'Complete recovery suffix required' USING ERRCODE='23514';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(m->'steps') LOOP
  IF applied ? (s->>'id') THEN CONTINUE;END IF;r=proof->'receipts'->(s->>'id');
  IF r->>'status' IS NULL OR r->>'status' NOT IN ('APPLIED','ABSENT') OR r->'generation' IS DISTINCT FROM i->'generation' OR (r->>'status'='ABSENT' AND r->'closed' IS DISTINCT FROM 'true'::jsonb) THEN RAISE EXCEPTION 'No UNKNOWN or open result' USING ERRCODE='23514';END IF;
  IF r->>'status'='ABSENT' THEN remaining=true;
  ELSE IF remaining OR r->>'payloadHash' IS DISTINCT FROM s->>'effect_hash' THEN RAISE EXCEPTION 'Monotonic exact prefix required' USING ERRCODE='23514';END IF;progress=progress+1;applied=applied||jsonb_build_object(s->>'id',jsonb_build_object('attempt',i->'attempt','generation',i->'generation','payloadHash',r->>'payloadHash'));END IF;
 END LOOP;
 FOR e IN SELECT * FROM d2.effect_receipts WHERE operation_id=o.id AND generation=o.lease_generation LOOP
  expected_key=CASE WHEN EXISTS(SELECT 1 FROM d4.step_intents WHERE operation_id=o.id) OR i->'multi_checkpoint'='true'::jsonb THEN o.id||'/'||o.context_pack_sha256||'/' ELSE o.id||'/'||o.context_pack_sha256 END;
  IF expected_key=o.id||'/'||o.context_pack_sha256 THEN r=proof->'receipts'->'step-1';IF e.effect_key<>expected_key THEN RAISE EXCEPTION 'Unknown logical effect' USING ERRCODE='23514';END IF;
  ELSE IF left(e.effect_key,length(expected_key))<>expected_key THEN RAISE EXCEPTION 'Unknown logical effect' USING ERRCODE='23514';END IF;r=proof->'receipts'->substr(e.effect_key,length(expected_key)+1);END IF;
  IF r IS NULL OR (e.status='APPLIED' AND r->>'status'<>'APPLIED') THEN RAISE EXCEPTION 'Applied fact cannot be revoked' USING ERRCODE='23514';END IF;
  -- Any archived payload assertion must agree; an incompatible hash is never adjudicated away.
  IF EXISTS(SELECT 1 FROM d4.recovery_observations ro WHERE ro.receipt_id=e.id AND (ro.receiver_id::text IS DISTINCT FROM proof->'receiver_seal'->>'receiverId' OR (ro.receipt->>'payloadHash' IS NOT NULL AND ro.receipt->>'payloadHash' IS DISTINCT FROM r->>'payloadHash'))) OR EXISTS(SELECT 1 FROM d4.lab_evidence le WHERE le.receipt_id=e.id AND le.proof->'receipt'->>'payloadHash' IS NOT NULL AND le.proof->'receipt'->>'payloadHash' IS DISTINCT FROM r->>'payloadHash') THEN RAISE EXCEPTION 'Historical payload mismatch' USING ERRCODE='23514';END IF;
 END LOOP;
 terminal=NOT remaining;
 IF progress=0 OR (NOT terminal AND (NOT coalesce((o.policy_snapshot->>'interruptible')::boolean,false) OR (SELECT count(*) FROM public.execution_attempts WHERE operation_id=o.id)>=coalesce((o.policy_snapshot->>'max_attempts')::int,3))) THEN RAISE EXCEPTION 'Progress and continuation budget required' USING ERRCODE='23514';END IF;
 IF (SELECT array_agg(account_id::text ORDER BY account_id) FROM d2.operation_accounts WHERE operation_id=o.id) IS DISTINCT FROM (SELECT array_agg(key ORDER BY key) FROM jsonb_each(m->'accounts')) OR (SELECT array_agg(account_id::text ORDER BY account_id) FROM d2.reservation_balances WHERE reservation_id=res.id) IS DISTINCT FROM (SELECT array_agg(key ORDER BY key) FROM jsonb_each(m->'accounts')) THEN RAISE EXCEPTION 'Complete account binding required' USING ERRCODE='23514';END IF;
 FOR a IN SELECT b.*,oa.units,ac.dimension,ac.unit,ac.window_start,ac.window_end FROM d2.reservation_balances b JOIN d2.operation_accounts oa ON oa.operation_id=o.id AND oa.account_id=b.account_id JOIN d2.accounts ac ON ac.id=b.account_id WHERE b.reservation_id=res.id ORDER BY b.account_id LOOP
  SELECT coalesce(sum((value->'cost'->>a.account_id::text)::numeric),0) INTO cost FROM jsonb_array_elements(m->'steps') WHERE applied ? (value->>'id');prev=coalesce((parent->'cumulative'->>a.account_id::text)::numeric,0);
  IF i->'multi_checkpoint' IS DISTINCT FROM 'true'::jsonb AND (i->>'continuation')::boolean THEN prev=4;END IF;
  delta=cost-a.consumed;
  IF a.units IS DISTINCT FROM (m->'accounts'->a.account_id::text->>'original')::numeric OR a.dimension IS DISTINCT FROM m->'accounts'->a.account_id::text->>'dimension' OR a.unit IS DISTINCT FROM m->'accounts'->a.account_id::text->>'unit'
  OR a.window_start IS DISTINCT FROM (m->'accounts'->a.account_id::text->>'start')::timestamptz OR a.window_end IS DISTINCT FROM (m->'accounts'->a.account_id::text->>'end')::timestamptz OR clock_timestamp()<a.window_start OR clock_timestamp()>=a.window_end
  OR delta<0 OR delta>a.outstanding OR a.consumed NOT IN (prev,cost) OR (a.consumed=prev AND a.outstanding<>a.units) OR (a.consumed<>prev AND a.outstanding<>0)
  THEN RAISE EXCEPTION 'Exact recoverable journal and live accounts required' USING ERRCODE='23514';END IF;
  cumulative=cumulative||jsonb_build_object(a.account_id::text,cost);consumes=consumes||jsonb_build_object(a.account_id::text,delta);releases=releases||jsonb_build_object(a.account_id::text,a.outstanding-delta);
 END LOOP;
 RETURN jsonb_build_object('applied',applied,'cumulative',cumulative,'consume',consumes,'release',releases,'terminal',terminal,'identity',jsonb_build_object('operation',i->'operation','attempt',i->'attempt','worker',i->'worker','resource',i->'resource','generation',i->'generation'),'attempt_count',(SELECT count(*) FROM public.execution_attempts WHERE operation_id=o.id));
END $$;

CREATE OR REPLACE FUNCTION d4.absence_evaluate(delivery uuid,proof jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,d2,d3,d4 AS $$
DECLARE i jsonb=d4.recovery_info(delivery);m jsonb=i->'recovery_manifest';o public.operations;res d2.reservations;parent jsonb=coalesce(i->'parent_evaluation','{}');applied jsonb=coalesce(parent->'applied','{}');remaining boolean=false;progress int=0;s jsonb;r jsonb;e record;a record;cost numeric;delta numeric;prev numeric;consumes jsonb='{}';releases jsonb='{}';cumulative jsonb='{}';terminal boolean;allowed jsonb;expected_key text;
BEGIN
 SELECT * INTO STRICT o FROM public.operations WHERE id=(i->>'operation')::uuid;SELECT * INTO STRICT res FROM d2.reservations WHERE operation_id=o.id;
 IF o.state NOT IN ('RECONCILING','BLOCKED_APPROVAL') OR (i->>'lease_expired')::boolean IS DISTINCT FROM true
 OR NOT EXISTS(SELECT 1 FROM public.operation_leases l WHERE l.operation_id=o.id AND l.attempt_id=(i->>'attempt')::uuid AND l.worker_id=(i->>'worker')::uuid AND l.fencing_generation=o.lease_generation AND o.lease_generation=(i->>'generation')::bigint)
 OR proof->>'schema' IS DISTINCT FROM 'd4.absence.proof.v1' OR proof->>'recovery_manifest_hash' IS DISTINCT FROM i->>'recovery_manifest_hash'
 OR proof->'receipt_basis' IS DISTINCT FROM i->'receipt_basis' OR proof->>'context_hash' IS DISTINCT FROM o.context_pack_sha256 OR proof->>'policy_hash' IS DISTINCT FROM encode(public.digest(o.policy_snapshot::text,'sha256'),'hex')
 OR EXISTS(SELECT 1 FROM jsonb_each(jsonb_build_object('operation',i->'operation','attempt',i->'attempt','worker',i->'worker','resource',i->'resource','generation',i->'generation')) x WHERE proof->x.key IS DISTINCT FROM x.value)
 OR proof->'process_stopped' IS DISTINCT FROM 'true'::jsonb OR proof->'artifact_valid' IS DISTINCT FROM 'true'::jsonb OR proof->'receiver_closed' IS DISTINCT FROM 'true'::jsonb
 OR coalesce(proof->>'host_observation_hash','') !~ '^[a-f0-9]{64}$' OR coalesce(proof->>'stdout_hash','') !~ '^[a-f0-9]{64}$' OR coalesce(proof->>'stderr_hash','') !~ '^[a-f0-9]{64}$'
 OR jsonb_typeof(proof->'receipts') IS DISTINCT FROM 'object' OR coalesce((proof->>'close_sequence')::bigint,0)<=0
 OR NOT EXISTS(SELECT 1 FROM d4.lab_grants g WHERE g.request->>'delivery'=delivery::text AND g.response->>'receiver_id'=proof->'receiver_seal'->>'receiverId')
 OR proof->'receiver_seal'->'steps' IS DISTINCT FROM proof->'receipts' OR proof->'receiver_seal'->'sequence' IS DISTINCT FROM proof->'close_sequence'
 OR EXISTS(SELECT 1 FROM jsonb_each(jsonb_build_object('operation',i->'operation','attempt',i->'attempt','worker',i->'worker','resource',i->'resource','generation',i->'generation')) x WHERE proof->'receiver_seal'->'identity'->x.key IS DISTINCT FROM x.value)
 OR (i->'multi_checkpoint'='true'::jsonb AND proof->'parent_checkpoint' IS DISTINCT FROM i->'parent_checkpoint')
 OR (i->'multi_checkpoint'='true'::jsonb AND NOT d4.parent_linked(o.id,(i->>'parent_checkpoint')::uuid,(i->>'attempt')::uuid,o.lease_generation))
 OR res.resource_id IS DISTINCT FROM (m->>'resource')::uuid OR res.pool IS DISTINCT FROM m->>'pool'
 THEN RAISE EXCEPTION 'Exact independently stopped sealed recovery required' USING ERRCODE='23514';END IF;
 -- Prior-generation evidence must remain explained by native checkpoints/resolutions.
 IF EXISTS(SELECT 1 FROM d2.effect_receipts er WHERE er.operation_id=o.id AND er.generation<>o.lease_generation AND NOT d4.receipt_resolved(er.id) AND NOT EXISTS(
 SELECT 1 FROM d4.multi_checkpoints cp JOIN d4.multi_proofs pr ON pr.id=cp.proof_id CROSS JOIN LATERAL jsonb_each(pr.proof->'receipts') rr WHERE cp.operation_id=o.id AND cp.source_generation=er.generation AND er.effect_key=o.id||'/'||o.context_pack_sha256||'/'||rr.key AND er.status=rr.value->>'status') AND NOT EXISTS(
 SELECT 1 FROM d4.checkpoints cp WHERE cp.operation_id=o.id AND cp.source_generation=er.generation AND ((er.effect_key=o.id||'/'||o.context_pack_sha256||'/step-1' AND er.status='APPLIED') OR (er.effect_key=o.id||'/'||o.context_pack_sha256||'/step-2' AND er.status='ABSENT')))) THEN RAISE EXCEPTION 'Prior evidence unresolved' USING ERRCODE='23514';END IF;
 SELECT coalesce(jsonb_agg(value->>'id' ORDER BY n),'[]') INTO allowed FROM jsonb_array_elements(m->'steps') WITH ORDINALITY x(value,n) WHERE NOT applied ? (value->>'id');
 IF (SELECT array_agg(key ORDER BY key) FROM jsonb_each(proof->'receipts')) IS DISTINCT FROM (SELECT array_agg(value#>>'{}' ORDER BY value#>>'{}') FROM jsonb_array_elements(allowed)) THEN RAISE EXCEPTION 'Complete recovery suffix required' USING ERRCODE='23514';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(m->'steps') LOOP
  IF applied ? (s->>'id') THEN CONTINUE;END IF;r=proof->'receipts'->(s->>'id');
  IF r->>'status' IS NULL OR r->>'status' NOT IN ('APPLIED','ABSENT') OR r->'generation' IS DISTINCT FROM i->'generation' OR (r->>'status'='ABSENT' AND r->'closed' IS DISTINCT FROM 'true'::jsonb) THEN RAISE EXCEPTION 'No UNKNOWN or open result' USING ERRCODE='23514';END IF;
  IF r->>'status'='ABSENT' THEN remaining=true;
  ELSE IF remaining OR r->>'payloadHash' IS DISTINCT FROM s->>'effect_hash' THEN RAISE EXCEPTION 'Monotonic exact prefix required' USING ERRCODE='23514';END IF;progress=progress+1;applied=applied||jsonb_build_object(s->>'id',jsonb_build_object('attempt',i->'attempt','generation',i->'generation','payloadHash',r->>'payloadHash'));END IF;
 END LOOP;
 FOR e IN SELECT * FROM d2.effect_receipts WHERE operation_id=o.id AND generation=o.lease_generation LOOP
  expected_key=CASE WHEN EXISTS(SELECT 1 FROM d4.step_intents WHERE operation_id=o.id) OR i->'multi_checkpoint'='true'::jsonb THEN o.id||'/'||o.context_pack_sha256||'/' ELSE o.id||'/'||o.context_pack_sha256 END;
  IF expected_key=o.id||'/'||o.context_pack_sha256 THEN r=proof->'receipts'->'step-1';IF e.effect_key<>expected_key THEN RAISE EXCEPTION 'Unknown logical effect' USING ERRCODE='23514';END IF;
  ELSE IF left(e.effect_key,length(expected_key))<>expected_key THEN RAISE EXCEPTION 'Unknown logical effect' USING ERRCODE='23514';END IF;r=proof->'receipts'->substr(e.effect_key,length(expected_key)+1);END IF;
  IF r IS NULL OR (e.status='APPLIED' AND r->>'status'<>'APPLIED') THEN RAISE EXCEPTION 'Applied fact cannot be revoked' USING ERRCODE='23514';END IF;
  -- Any archived payload assertion must agree; an incompatible hash is never adjudicated away.
  IF EXISTS(SELECT 1 FROM d4.recovery_observations ro WHERE ro.receipt_id=e.id AND (ro.receiver_id::text IS DISTINCT FROM proof->'receiver_seal'->>'receiverId' OR (ro.receipt->>'payloadHash' IS NOT NULL AND ro.receipt->>'payloadHash' IS DISTINCT FROM r->>'payloadHash'))) OR EXISTS(SELECT 1 FROM d4.lab_evidence le WHERE le.receipt_id=e.id AND le.proof->'receipt'->>'payloadHash' IS NOT NULL AND le.proof->'receipt'->>'payloadHash' IS DISTINCT FROM r->>'payloadHash') THEN RAISE EXCEPTION 'Historical payload mismatch' USING ERRCODE='23514';END IF;
 END LOOP;
 terminal=NOT remaining;
 IF progress<>0 OR terminal OR (SELECT count(*) FROM public.execution_attempts WHERE operation_id=o.id)>=coalesce((o.policy_snapshot->>'max_attempts')::int,3) THEN RAISE EXCEPTION 'No new progress and retry budget required' USING ERRCODE='23514';END IF;
 IF (SELECT array_agg(account_id::text ORDER BY account_id) FROM d2.operation_accounts WHERE operation_id=o.id) IS DISTINCT FROM (SELECT array_agg(key ORDER BY key) FROM jsonb_each(m->'accounts')) OR (SELECT array_agg(account_id::text ORDER BY account_id) FROM d2.reservation_balances WHERE reservation_id=res.id) IS DISTINCT FROM (SELECT array_agg(key ORDER BY key) FROM jsonb_each(m->'accounts')) THEN RAISE EXCEPTION 'Complete account binding required' USING ERRCODE='23514';END IF;
 FOR a IN SELECT b.*,oa.units,ac.dimension,ac.unit,ac.window_start,ac.window_end FROM d2.reservation_balances b JOIN d2.operation_accounts oa ON oa.operation_id=o.id AND oa.account_id=b.account_id JOIN d2.accounts ac ON ac.id=b.account_id WHERE b.reservation_id=res.id ORDER BY b.account_id LOOP
  SELECT coalesce(sum((value->'cost'->>a.account_id::text)::numeric),0) INTO cost FROM jsonb_array_elements(m->'steps') WHERE applied ? (value->>'id');prev=coalesce((parent->'cumulative'->>a.account_id::text)::numeric,0);
  IF i->'multi_checkpoint' IS DISTINCT FROM 'true'::jsonb AND (i->>'continuation')::boolean THEN prev=4;END IF;
  delta=cost-a.consumed;
  IF a.units IS DISTINCT FROM (m->'accounts'->a.account_id::text->>'original')::numeric OR a.dimension IS DISTINCT FROM m->'accounts'->a.account_id::text->>'dimension' OR a.unit IS DISTINCT FROM m->'accounts'->a.account_id::text->>'unit'
  OR a.window_start IS DISTINCT FROM (m->'accounts'->a.account_id::text->>'start')::timestamptz OR a.window_end IS DISTINCT FROM (m->'accounts'->a.account_id::text->>'end')::timestamptz OR clock_timestamp()<a.window_start OR clock_timestamp()>=a.window_end
  OR delta<0 OR delta>a.outstanding OR a.consumed NOT IN (prev,cost) OR (a.consumed=prev AND a.outstanding<>a.units) OR (a.consumed<>prev AND a.outstanding<>0)
  THEN RAISE EXCEPTION 'Exact recoverable journal and live accounts required' USING ERRCODE='23514';END IF;
  cumulative=cumulative||jsonb_build_object(a.account_id::text,cost);consumes=consumes||jsonb_build_object(a.account_id::text,delta);releases=releases||jsonb_build_object(a.account_id::text,a.outstanding-delta);
 END LOOP;
 RETURN jsonb_build_object('applied',applied,'cumulative',cumulative,'consume',consumes,'release',releases,'terminal',terminal,'identity',jsonb_build_object('operation',i->'operation','attempt',i->'attempt','worker',i->'worker','resource',i->'resource','generation',i->'generation'),'attempt_count',(SELECT count(*) FROM public.execution_attempts WHERE operation_id=o.id));
END $$;

CREATE OR REPLACE FUNCTION d4.absence_record(pid uuid,delivery uuid,proof jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,d2,d3,d4 AS $$
DECLARE old d4.recovery_proofs;ev jsonb;
BEGIN
 PERFORM d3.lock_state();SELECT * INTO old FROM d4.recovery_proofs WHERE id=pid;IF FOUND THEN IF old.delivery_id IS DISTINCT FROM delivery OR old.proof IS DISTINCT FROM proof OR old.proof->>'schema' IS DISTINCT FROM 'd4.absence.proof.v1' THEN RAISE EXCEPTION 'Recovery proof conflict' USING ERRCODE='23514';END IF;RETURN old.evaluation;END IF;
 IF pid IS NULL THEN RAISE EXCEPTION 'Proof ID required' USING ERRCODE='23514';END IF;ev=d4.absence_evaluate(delivery,proof);INSERT INTO d4.recovery_proofs VALUES(pid,delivery,proof,ev,proof->'receipt_basis');RETURN ev;
END $$;

CREATE OR REPLACE FUNCTION d4.absence_settle(cid uuid,pid uuid,expected_version bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,d2,d3,d4 AS $$
DECLARE req jsonb=jsonb_build_object('action','ABSENCE_SETTLE','proof',pid,'version',expected_version);prior jsonb;p d4.recovery_proofs;i jsonb;o public.operations;ev jsonb;res d2.reservations;entries jsonb;cp_proof jsonb;new_state text;result jsonb;
BEGIN
 PERFORM d3.lock_state();prior=d4.checkpoint_previous(cid,req);IF prior IS NOT NULL THEN RETURN prior;END IF;SELECT * INTO STRICT p FROM d4.recovery_proofs WHERE id=pid;i=d4.recovery_info(p.delivery_id);SELECT * INTO STRICT o FROM public.operations WHERE id=(i->>'operation')::uuid;
 IF o.row_version IS DISTINCT FROM expected_version THEN RAISE EXCEPTION 'Recovery version changed' USING ERRCODE='40001';END IF;
 ev=d4.absence_evaluate(p.delivery_id,p.proof);IF ev IS DISTINCT FROM p.evaluation THEN RAISE EXCEPTION 'Recovery evaluation changed' USING ERRCODE='40001';END IF;
 IF o.state='BLOCKED_APPROVAL' THEN UPDATE public.operations SET state='RECONCILING',row_version=row_version+1 WHERE id=o.id;PERFORM d2.record_transition(public.gen_random_uuid(),'OPERATION',o.id,'BLOCKED_APPROVAL','RECONCILING',o.row_version+1,'CONTROL_PLANE','Authoritative monotonic recovery');o.row_version=o.row_version+1;o.state='RECONCILING';END IF;
 SELECT * INTO STRICT res FROM d2.reservations WHERE operation_id=o.id;
 SELECT jsonb_agg(jsonb_build_object('account_id',key,'settled',value) ORDER BY key) INTO entries FROM jsonb_each(ev->'release');PERFORM d2.capacity(public.gen_random_uuid(),jsonb_build_object('action','RELEASE','reservation_id',res.id,'entries',entries,'reason','Closed recovery remainder'));
 IF p.receipt_basis IS DISTINCT FROM d4.receipt_basis(o.id,o.lease_generation) OR EXISTS(SELECT 1 FROM d2.operation_accounts oa JOIN d2.accounts ac ON ac.id=oa.account_id WHERE oa.operation_id=o.id AND (clock_timestamp()<ac.window_start OR clock_timestamp()>=ac.window_end)) THEN RAISE EXCEPTION 'Recovery basis/window changed during settlement' USING ERRCODE='23514';END IF;
 new_state='RETRY_PENDING';
 UPDATE public.operations SET state=new_state,row_version=row_version+1 WHERE id=o.id;UPDATE public.execution_attempts SET state='FAILED',finished_at=clock_timestamp() WHERE id=(i->>'attempt')::uuid;
 PERFORM d2.record_transition(cid,'OPERATION',o.id,'RECONCILING',new_state,o.row_version+1,'CONTROL_PLANE','Conclusive sealed recovery');
 DELETE FROM public.operation_leases WHERE operation_id=o.id;
 INSERT INTO d4.absence_seals VALUES(cid,pid,p.delivery_id,o.id,o.lease_generation,(i->>'attempt')::uuid,res.id,o.row_version+1);
 INSERT INTO d4.recovery_settlements VALUES(cid,pid,o.id,o.lease_generation,d4.receipt_basis(o.id,o.lease_generation),(ev->>'terminal')::boolean);
 result=jsonb_build_object('state',new_state,'seal_id',cid,'resolution_id',cid,'row_version',o.row_version+1);INSERT INTO d4.checkpoint_commands VALUES(cid,req,result);INSERT INTO public.outbox_events(aggregate_type,aggregate_id,event_type,payload) VALUES('OPERATION',o.id,'D4_ABSENCE_SETTLED',result);RETURN result;
END $$;

CREATE FUNCTION d4.absence_settled(seal uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,d2,d4 AS $$
 SELECT EXISTS(SELECT 1 FROM d4.absence_seals s JOIN d4.recovery_proofs p ON p.id=s.proof_id JOIN public.operations o ON o.id=s.operation_id WHERE s.id=seal AND d4.recovery_current(s.id)
 AND NOT EXISTS(SELECT 1 FROM public.execution_evidence WHERE attempt_id=s.attempt_id AND evidence_type='ACCEPTANCE_FAIL')
 AND NOT EXISTS(SELECT 1 FROM d2.reservation_balances b JOIN d2.accounts a ON a.id=b.account_id WHERE b.reservation_id=s.reservation_id AND (b.outstanding<>0 OR b.consumed IS DISTINCT FROM (p.evaluation->'cumulative'->>b.account_id::text)::numeric OR clock_timestamp()<a.window_start OR clock_timestamp()>=a.window_end)));
$$;

CREATE OR REPLACE FUNCTION d4.absence_safe(oid uuid,gen bigint) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,d4 AS $$
 SELECT EXISTS(SELECT 1 FROM d4.absence_seals s JOIN d4.absence_authorizations a ON a.seal_id=s.id JOIN public.operations o ON o.id=s.operation_id WHERE s.operation_id=oid AND s.generation=gen AND o.lease_generation=gen AND o.state='READY' AND o.row_version=a.authorized_version AND d4.absence_settled(s.id) AND NOT EXISTS(SELECT 1 FROM d4.absence_links WHERE seal_id=s.id));
$$;

CREATE OR REPLACE FUNCTION d4.absence_authorize(cid uuid,seal uuid,expected_version bigint,reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,d2,d3,d4 AS $$
DECLARE req jsonb=jsonb_build_object('action','ABSENCE_AUTHORIZE','seal',seal,'version',expected_version,'reason',reason);prior jsonb;s d4.absence_seals;o public.operations;result jsonb;
BEGIN
 PERFORM d3.lock_state();prior=d4.checkpoint_previous(cid,req);IF prior IS NOT NULL THEN RETURN prior;END IF;SELECT * INTO STRICT s FROM d4.absence_seals WHERE id=seal;SELECT * INTO STRICT o FROM public.operations WHERE id=s.operation_id;
 IF o.state NOT IN ('RETRY_PENDING','READY') OR o.row_version IS DISTINCT FROM expected_version OR o.lease_generation<>s.generation OR NOT d4.absence_settled(s.id) OR EXISTS(SELECT 1 FROM d4.absence_links WHERE seal_id=seal) OR (SELECT count(*) FROM public.execution_attempts WHERE operation_id=o.id)>=coalesce((o.policy_snapshot->>'max_attempts')::int,3) OR reason IS NULL OR length(btrim(reason)) NOT BETWEEN 1 AND 512 THEN RAISE EXCEPTION 'Current unused absence, authorization and budget required' USING ERRCODE='23514';END IF;
 UPDATE public.operations SET state='READY',row_version=row_version+1 WHERE id=o.id;IF o.state<>'READY' THEN PERFORM d2.record_transition(cid,'OPERATION',o.id,o.state,'READY',o.row_version+1,'CONTROL_PLANE','Explicit absence retry');END IF;
 INSERT INTO d4.absence_authorizations VALUES(cid,seal,o.row_version+1,reason);result=jsonb_build_object('state','READY','row_version',o.row_version+1);INSERT INTO d4.checkpoint_commands VALUES(cid,req,result);RETURN result;
END $$;

CREATE OR REPLACE FUNCTION d4.commit_checkpoint(cid uuid,rid uuid,pid uuid,expected_version bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,public,d2,d3,d4 AS $$
DECLARE req jsonb=jsonb_build_object('action','COMMIT_CHECKPOINT','request',rid,'proof',pid,'version',expected_version);prior jsonb;
 r d4.checkpoint_requests;pr d4.checkpoint_proofs;op public.operations;i d4.step_intents;res d2.reservations;info jsonb;entries jsonb;releases jsonb;row record;delta numeric;result jsonb;
BEGIN
 PERFORM d3.lock_state();prior=d4.checkpoint_previous(cid,req);IF prior IS NOT NULL THEN RETURN prior;END IF;
 SELECT * INTO STRICT r FROM d4.checkpoint_requests WHERE id=rid;SELECT * INTO STRICT pr FROM d4.checkpoint_proofs WHERE id=pid AND request_id=rid;
 info=d4.lab_inspect(r.delivery_id);SELECT * INTO STRICT op FROM public.operations WHERE id=r.operation_id;
 SELECT * INTO STRICT i FROM d4.step_intents WHERE operation_id=op.id;SELECT * INTO STRICT res FROM d2.reservations WHERE operation_id=op.id;
 IF op.state<>'RUNNING' OR (info->>'lease_expired')::boolean OR op.row_version IS DISTINCT FROM expected_version OR r.expected_version IS DISTINCT FROM expected_version
  OR info->>'context_hash' IS DISTINCT FROM op.context_pack_sha256 OR info->>'policy_hash' IS DISTINCT FROM encode(public.digest(op.policy_snapshot::text,'sha256'),'hex')
  OR r.attempt_id IS DISTINCT FROM (info->>'attempt')::uuid OR r.generation IS DISTINCT FROM op.lease_generation
  OR NOT coalesce((op.policy_snapshot->>'interruptible')::boolean,false)
  OR pr.proof->>'context_hash' IS DISTINCT FROM op.context_pack_sha256 OR pr.proof->>'manifest_hash' IS DISTINCT FROM i.manifest_hash
  OR pr.proof->>'policy_hash' IS DISTINCT FROM encode(public.digest(op.policy_snapshot::text,'sha256'),'hex')
  OR EXISTS(SELECT 1 FROM d4.checkpoints WHERE operation_id=op.id)
  OR EXISTS(SELECT 1 FROM d4.unresolved_receipts er WHERE er.operation_id=op.id AND (er.status='UNKNOWN' OR er.generation<>r.generation))
  OR (SELECT count(*) FROM d2.operation_accounts WHERE operation_id=op.id)<>1
  OR EXISTS(SELECT 1 FROM d4.unresolved_receipts er WHERE er.operation_id=op.id AND
    NOT ((er.effect_key=op.id||'/'||op.context_pack_sha256||'/step-1' AND er.status='APPLIED') OR (er.effect_key=op.id||'/'||op.context_pack_sha256||'/step-2' AND er.status='ABSENT')))
  OR EXISTS(SELECT 1 FROM d4.unresolved_receipts WHERE operation_id=op.id GROUP BY effect_key,generation HAVING count(DISTINCT status)>1)
 THEN RAISE EXCEPTION 'Live sealed checkpoint identity/version required' USING ERRCODE='23514';END IF;
 entries='[]';
 FOR row IN SELECT b.*,a.units FROM d2.reservation_balances b JOIN d2.operation_accounts a ON a.account_id=b.account_id AND a.operation_id=op.id WHERE b.reservation_id=res.id ORDER BY b.account_id LOOP
  delta=4-row.consumed;
  IF delta<0 OR delta>row.outstanding OR row.units<>10 THEN RAISE EXCEPTION 'Verified bounded incremental consumption required' USING ERRCODE='23514';END IF;
  entries=entries||jsonb_build_array(jsonb_build_object('account_id',row.account_id,'settled',delta,'consumed',delta));
 END LOOP;
 IF jsonb_array_length(entries)=0 THEN RAISE EXCEPTION 'All physical accounts required' USING ERRCODE='23514';END IF;
 PERFORM d2.capacity(public.gen_random_uuid(),jsonb_build_object('action','CONSUME','reservation_id',res.id,'entries',entries,'reason','Verified checkpoint incremental consumption'));
 SELECT jsonb_agg(jsonb_build_object('account_id',account_id,'settled',outstanding) ORDER BY account_id) INTO releases FROM d2.reservation_balances WHERE reservation_id=res.id;
 PERFORM d2.capacity(public.gen_random_uuid(),jsonb_build_object('action','RELEASE','reservation_id',res.id,'entries',releases,'reason','Sealed checkpoint remainder'));
 INSERT INTO d2.effect_receipts(operation_id,generation,effect_key,status,evidence_ref) VALUES(op.id,r.generation,op.id||'/'||op.context_pack_sha256||'/step-1','APPLIED','checkpoint-proof/'||pid),(op.id,r.generation,op.id||'/'||op.context_pack_sha256||'/step-2','ABSENT','checkpoint-proof/'||pid);
 UPDATE public.execution_attempts SET state='CANCELLED',finished_at=clock_timestamp() WHERE id=r.attempt_id;
 DELETE FROM public.operation_leases WHERE operation_id=op.id;
 UPDATE public.operations SET state='CANCELLED',row_version=row_version+1 WHERE id=op.id;
 PERFORM d2.record_transition(cid,'OPERATION',op.id,'RUNNING','CANCELLED',op.row_version+1,'CONTROL_PLANE','Sealed partial checkpoint');
 INSERT INTO d4.checkpoints VALUES(cid,rid,pid,op.id,r.attempt_id,r.generation,res.id,op.context_pack_sha256,encode(public.digest(op.policy_snapshot::text,'sha256'),'hex'),i.manifest_hash,op.row_version+1);
 result=jsonb_build_object('checkpoint_id',cid,'state','CANCELLED','row_version',op.row_version+1);
 INSERT INTO d4.checkpoint_commands VALUES(cid,req,result);
 INSERT INTO public.outbox_events(aggregate_type,aggregate_id,event_type,payload) VALUES('OPERATION',op.id,'D4_CHECKPOINT_COMMITTED',result);
 RETURN result;
END $$;

CREATE OR REPLACE FUNCTION d4.record_checkpoint_proof(cid uuid,rid uuid,proof jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,public,d2,d3,d4 AS $$
DECLARE r d4.checkpoint_requests;i d4.step_intents;op public.operations;old d4.checkpoint_proofs;
BEGIN
 PERFORM d3.lock_state();SELECT * INTO STRICT r FROM d4.checkpoint_requests WHERE id=rid;
 SELECT * INTO STRICT i FROM d4.step_intents WHERE operation_id=r.operation_id;SELECT * INTO STRICT op FROM public.operations WHERE id=r.operation_id;
 IF cid IS NULL OR proof->>'schema' IS DISTINCT FROM 'd4.checkpoint.proof.v1' OR proof->>'manifest_hash' IS DISTINCT FROM i.manifest_hash
  OR proof->>'context_hash' IS DISTINCT FROM op.context_pack_sha256 OR proof->>'policy_hash' IS DISTINCT FROM encode(public.digest(op.policy_snapshot::text,'sha256'),'hex')
  OR proof->>'attempt' IS DISTINCT FROM r.attempt_id::text OR proof->>'generation' IS DISTINCT FROM r.generation::text
  OR proof->'process_stopped' IS DISTINCT FROM 'true'::jsonb OR proof->'artifact_valid' IS DISTINCT FROM 'true'::jsonb
  OR proof->'receiver_closed' IS DISTINCT FROM 'true'::jsonb OR coalesce((proof->>'close_sequence')::bigint,0)<=0
  OR proof->'steps' IS DISTINCT FROM '{"step-1":"APPLIED","step-2":"ABSENT"}'::jsonb
  OR proof->'consumed_units' IS DISTINCT FROM '4'::jsonb
  OR i.manifest IS DISTINCT FROM '{"schema":"d4.steps.v1","steps":[{"id":"step-1","units":4},{"id":"step-2","units":6}]}'::jsonb
  OR EXISTS(SELECT 1 FROM d4.unresolved_receipts WHERE operation_id=op.id AND status='UNKNOWN')
 THEN RAISE EXCEPTION 'Complete independent sealed partial proof required' USING ERRCODE='23514';END IF;
 SELECT * INTO old FROM d4.checkpoint_proofs WHERE id=cid;
 IF FOUND THEN IF old.request_id IS DISTINCT FROM rid OR old.proof IS DISTINCT FROM proof THEN RAISE EXCEPTION 'Proof replay conflict' USING ERRCODE='23514';END IF;
 ELSE INSERT INTO d4.checkpoint_proofs VALUES(cid,rid,proof);END IF;
 RETURN jsonb_build_object('proof_id',cid);
END $$;

CREATE OR REPLACE FUNCTION d4.multi_evaluate(delivery uuid,proof jsonb,terminal boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,d2,d3,d4 AS $$
DECLARE info jsonb=d4.multi_inspect(delivery);op public.operations;m jsonb=info->'manifest';parent jsonb=coalesce(info->'parent_evaluation','{}');applied jsonb=coalesce(parent->'applied','{}');
 cumulative jsonb='{}';consumes jsonb='{}';releases jsonb='{}';s jsonb;rr jsonb;row record;res d2.reservations;cost numeric;prev numeric;delta numeric;remaining boolean=false;progress integer=0;attempts integer;
BEGIN
 IF NOT d4.multi_manifest_typed(m) THEN RAISE EXCEPTION 'Typed compatible v2 intention required' USING ERRCODE='23514';END IF;
 SELECT * INTO STRICT op FROM public.operations WHERE id=(info->>'operation')::uuid;SELECT * INTO STRICT res FROM d2.reservations WHERE operation_id=op.id;
 SELECT count(*) INTO attempts FROM public.execution_attempts WHERE operation_id=op.id;
 IF info->'multi_checkpoint' IS DISTINCT FROM 'true'::jsonb OR op.state IS DISTINCT FROM (CASE WHEN terminal THEN 'VERIFYING' ELSE 'RUNNING' END)
 OR (info->>'lease_expired')::boolean IS DISTINCT FROM false OR proof->>'schema' IS DISTINCT FROM 'd4.checkpoint.proof.v2'
 OR proof->'parent_checkpoint' IS DISTINCT FROM info->'parent_checkpoint'
 OR proof->>'manifest_hash' IS DISTINCT FROM info->>'manifest_hash' OR proof->>'context_hash' IS DISTINCT FROM info->>'context_hash' OR proof->>'policy_hash' IS DISTINCT FROM info->>'policy_hash'
 OR proof->>'operation' IS DISTINCT FROM info->>'operation' OR proof->>'attempt' IS DISTINCT FROM info->>'attempt' OR proof->>'worker' IS DISTINCT FROM info->>'worker' OR proof->>'resource' IS DISTINCT FROM info->>'resource' OR proof->>'generation' IS DISTINCT FROM info->>'generation'
 OR op.context_pack_sha256 IS DISTINCT FROM info->>'context_hash' OR encode(public.digest(op.policy_snapshot::text,'sha256'),'hex') IS DISTINCT FROM info->>'policy_hash'
 OR proof->'process_stopped' IS DISTINCT FROM 'true'::jsonb OR proof->'artifact_valid' IS DISTINCT FROM 'true'::jsonb OR proof->'receiver_closed' IS DISTINCT FROM 'true'::jsonb OR coalesce((proof->>'close_sequence')::bigint,0)<=0
 OR coalesce(proof->>'host_observation_hash','') !~ '^[a-f0-9]{64}$' OR coalesce(proof->>'stdout_hash','') !~ '^[a-f0-9]{64}$' OR coalesce(proof->>'stderr_hash','') !~ '^[a-f0-9]{64}$'
 OR NOT d4.multi_effects_safe(op.id) OR attempts>coalesce((op.policy_snapshot->>'max_attempts')::int,3) OR (NOT terminal AND attempts>=coalesce((op.policy_snapshot->>'max_attempts')::int,3))
 OR res.resource_id IS DISTINCT FROM (m->>'resource')::uuid OR res.pool IS DISTINCT FROM m->>'pool'
 OR NOT d4.parent_linked(op.id,(info->>'parent_checkpoint')::uuid,(info->>'attempt')::uuid,op.lease_generation)
 OR jsonb_typeof(proof->'receipts') IS DISTINCT FROM 'object'
 OR (SELECT array_agg(key ORDER BY key) FROM jsonb_each(proof->'receipts')) IS DISTINCT FROM (SELECT array_agg(value#>>'{}' ORDER BY value#>>'{}') FROM jsonb_array_elements(info->'allowed_steps'))
 THEN RAISE EXCEPTION 'Exact live independently sealed v2 proof required' USING ERRCODE='23514';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(m->'steps') LOOP
  IF applied ? (s->>'id') THEN CONTINUE;END IF;
  rr=proof->'receipts'->(s->>'id');
  IF (rr->>'generation')::bigint IS DISTINCT FROM op.lease_generation OR rr->>'status' NOT IN ('APPLIED','ABSENT') OR rr->>'status' IS NULL
   OR (rr->>'status'='ABSENT' AND rr->'closed' IS DISTINCT FROM 'true'::jsonb) THEN RAISE EXCEPTION 'No UNKNOWN or unbound absence' USING ERRCODE='23514';END IF;
  IF rr->>'status'='ABSENT' THEN remaining=true;
  ELSE
   IF remaining OR rr->>'payloadHash' IS DISTINCT FROM s->>'effect_hash' THEN RAISE EXCEPTION 'Ordered exact effect required' USING ERRCODE='23514';END IF;
   progress=progress+1;applied=applied||jsonb_build_object(s->>'id',jsonb_build_object('attempt',info->'attempt','generation',op.lease_generation,'payloadHash',rr->>'payloadHash'));
  END IF;
 END LOOP;
 IF progress=0 OR terminal IS DISTINCT FROM (NOT remaining) THEN RAISE EXCEPTION 'New progress and exact finality required' USING ERRCODE='23514';END IF;
 IF (SELECT array_agg(account_id::text ORDER BY account_id::text) FROM d2.operation_accounts WHERE operation_id=op.id) IS DISTINCT FROM (SELECT array_agg(key ORDER BY key) FROM jsonb_each(m->'accounts'))
 OR (SELECT array_agg(account_id::text ORDER BY account_id::text) FROM d2.reservation_balances WHERE reservation_id=res.id) IS DISTINCT FROM (SELECT array_agg(key ORDER BY key) FROM jsonb_each(m->'accounts'))
 THEN RAISE EXCEPTION 'All frozen accounts required' USING ERRCODE='23514';END IF;
 FOR row IN SELECT b.*,oa.units,ac.window_start,ac.window_end,ac.dimension,ac.unit FROM d2.reservation_balances b JOIN d2.operation_accounts oa ON oa.operation_id=op.id AND oa.account_id=b.account_id JOIN d2.accounts ac ON ac.id=b.account_id WHERE b.reservation_id=res.id ORDER BY b.account_id LOOP
  SELECT coalesce(sum((value->'cost'->>row.account_id::text)::numeric),0) INTO cost FROM jsonb_array_elements(m->'steps') WHERE applied ? (value->>'id');
  prev=coalesce((parent->'cumulative'->>row.account_id::text)::numeric,0);delta=cost-prev;
  IF row.units IS DISTINCT FROM (m->'accounts'->row.account_id::text->>'original')::numeric OR row.window_start IS DISTINCT FROM (m->'accounts'->row.account_id::text->>'start')::timestamptz OR row.window_end IS DISTINCT FROM (m->'accounts'->row.account_id::text->>'end')::timestamptz
   OR row.dimension IS DISTINCT FROM m->'accounts'->row.account_id::text->>'dimension' OR row.unit IS DISTINCT FROM m->'accounts'->row.account_id::text->>'unit'
   OR clock_timestamp()<row.window_start OR clock_timestamp()>=row.window_end OR delta<0 OR delta>row.units
   OR (NOT terminal AND (row.consumed<>prev OR row.outstanding<>row.units)) OR (terminal AND (row.consumed<>cost OR row.outstanding<>0))
  THEN RAISE EXCEPTION 'Atomic complete account settlement required' USING ERRCODE='23514';END IF;
  cumulative=cumulative||jsonb_build_object(row.account_id::text,cost);consumes=consumes||jsonb_build_object(row.account_id::text,delta);releases=releases||jsonb_build_object(row.account_id::text,row.units-delta);
 END LOOP;
 RETURN jsonb_build_object('applied',applied,'cumulative',cumulative,'consume',consumes,'release',releases,'identity',jsonb_build_object('operation',info->'operation','attempt',info->'attempt','worker',info->'worker','resource',info->'resource','generation',info->'generation'),'attempt_count',attempts,'terminal',terminal);
END $$;

CREATE OR REPLACE FUNCTION d4.dispatch_continuation(cid uuid,req jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,d2,d3,d4 AS $$
DECLARE prior jsonb;cp d4.multi_checkpoints;au uuid;body jsonb;captured jsonb;rel text;result jsonb;mi d4.multi_intents;abs d4.absence_seals;absau uuid;
BEGIN
 PERFORM d3.lock_state();prior=d3.previous_command(cid,req);IF prior IS NOT NULL THEN RETURN prior;END IF;
 SELECT * INTO mi FROM d4.multi_intents WHERE operation_id=(req->>'operation_id')::uuid;
 IF mi.operation_id IS NOT NULL AND NOT d4.multi_manifest_typed(mi.manifest) THEN RAISE EXCEPTION 'Typed compatible v2 intention required' USING ERRCODE='23514';END IF;
 IF mi.operation_id IS NOT NULL AND (
  (mi.manifest->>'resource')::uuid IS DISTINCT FROM (req->>'resource_id')::uuid
  OR NOT EXISTS(SELECT 1 FROM d3.estimate_heads eh JOIN d3.estimates e ON e.id=eh.estimate_id WHERE eh.operation_id=mi.operation_id AND eh.resource_id=(req->>'resource_id')::uuid AND e.units=(SELECT jsonb_object_agg(key,value->'original') FROM jsonb_each(mi.manifest->'accounts')))
  OR NOT EXISTS(SELECT 1 FROM d3.plan_manifests pm CROSS JOIN LATERAL jsonb_array_elements(pm.result->'decisions') d WHERE pm.planning_run_id=(req->>'plan_id')::uuid AND d->>'operationId'=mi.operation_id::text AND d->>'pool'=mi.manifest->>'pool')
  OR NOT EXISTS(SELECT 1 FROM public.operations op JOIN d4.lab_intents li ON li.operation_id=op.id WHERE op.id=mi.operation_id AND op.context_pack_sha256=encode(public.digest(li.context_bytes,'sha256'),'hex') AND convert_from(li.context_bytes,'UTF8')::jsonb->'step_manifest'=mi.manifest))
 THEN RAISE EXCEPTION 'Frozen v2 intent/mapping must match initial and retry CLAIM' USING ERRCODE='23514';END IF;
 SELECT s.* INTO abs FROM d4.absence_seals s WHERE s.operation_id=(req->>'operation_id')::uuid AND d4.absence_safe(s.operation_id,s.generation);
 IF abs.id IS NOT NULL THEN SELECT a.id INTO STRICT absau FROM d4.absence_authorizations a WHERE a.seal_id=abs.id AND a.authorized_version=(SELECT row_version FROM public.operations WHERE id=abs.operation_id);END IF;
 SELECT h.* INTO cp FROM d4.multi_heads h WHERE h.operation_id=(req->>'operation_id')::uuid AND d4.multi_safe(h.operation_id,h.source_generation);
 IF mi.operation_id IS NOT NULL OR abs.id IS NOT NULL THEN
  body=d3.state_body();SELECT c.body INTO STRICT captured FROM d3.plan_manifests m JOIN d3.captures c ON c.id=m.capture_id WHERE m.planning_run_id=(req->>'plan_id')::uuid;
  FOREACH rel IN ARRAY ARRAY['d4.multi_intents','d4.multi_proofs','d4.multi_checkpoints','d4.multi_authorizations','d4.multi_links','d4.multi_heads','d4.recovery_proofs','d4.recovery_settlements','d4.recovery_observations','d4.absence_seals','d4.absence_authorizations','d4.absence_links'] LOOP
   IF body->rel IS DISTINCT FROM captured->rel THEN RAISE EXCEPTION 'v2 admission readset changed' USING ERRCODE='40001';END IF;
  END LOOP;
 END IF;
 IF cp.id IS NOT NULL THEN SELECT id INTO STRICT au FROM d4.multi_authorizations WHERE checkpoint_id=cp.id;END IF;
 result=d4.dispatch_continuation_before_i8(cid,req);
 IF cp.id IS NOT NULL THEN INSERT INTO d4.multi_links VALUES(cp.id,au,(result->>'attempt_id')::uuid,(result->>'generation')::bigint);END IF;
 IF abs.id IS NOT NULL THEN INSERT INTO d4.absence_links VALUES(abs.id,absau,(result->>'attempt_id')::uuid,(result->>'generation')::bigint);END IF;
 RETURN result;
END $$;

CREATE OR REPLACE FUNCTION d4.worker_execution_status(wid uuid,delivery uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,d2,d3,d4 AS $$
DECLARE info jsonb;safe boolean;
BEGIN
 PERFORM d3.lock_state();PERFORM d4.require_worker(wid);
 IF wid IS NULL OR delivery IS NULL OR NOT EXISTS(SELECT 1 FROM d4.deliveries WHERE id=delivery AND worker_id=wid)
 THEN RAISE EXCEPTION 'Execution status ownership mismatch' USING ERRCODE='42501';END IF;
 info=d4.lab_inspect(delivery);
 SELECT op.state='COMPLETED' AND a.state='COMPLETED' AND op.lease_generation=(info->>'generation')::bigint
  AND NOT EXISTS(SELECT 1 FROM public.operation_leases WHERE operation_id=op.id)
  AND NOT EXISTS(SELECT 1 FROM d2.reservations r JOIN d2.reservation_balances b ON b.reservation_id=r.id WHERE r.operation_id=op.id AND b.outstanding<>0)
  AND EXISTS(SELECT 1 FROM public.execution_evidence WHERE attempt_id=a.id AND evidence_type='ACCEPTANCE_PASS')
  AND NOT EXISTS(SELECT 1 FROM public.execution_evidence WHERE attempt_id=a.id AND evidence_type='ACCEPTANCE_FAIL')
  AND NOT EXISTS(SELECT 1 FROM d4.unresolved_receipts WHERE operation_id=op.id AND status='UNKNOWN')
  AND NOT EXISTS(SELECT 1 FROM d4.unresolved_receipts WHERE operation_id=op.id GROUP BY generation,effect_key HAVING count(DISTINCT status)>1)
  AND (EXISTS(SELECT 1 FROM d4.lab_evidence e WHERE e.delivery_id=delivery AND e.acceptance AND e.effect_status='APPLIED'
    AND e.proof->'process_stopped'='true'::jsonb AND e.proof->'receiver_closed'='true'::jsonb AND e.proof->'artifact_valid'='true'::jsonb)
   OR EXISTS(SELECT 1 FROM d4.recovery_settlements rs JOIN d4.recovery_proofs rp ON rp.id=rs.proof_id WHERE rs.operation_id=op.id AND rs.generation=op.lease_generation AND rs.terminal AND rp.proof->>'attempt'=a.id::text AND d4.recovery_current(rs.id))
   OR EXISTS(SELECT 1 FROM d4.checkpoint_commands c WHERE c.request->>'action'='ACCEPT_CONTINUATION' AND c.request->>'delivery'=delivery::text
    AND c.request->'proof'->'process_stopped'='true'::jsonb AND c.request->'proof'->'receiver_closed'='true'::jsonb
    AND c.request->'proof'->>'attempt'=a.id::text AND c.request->'proof'->>'generation'=info->>'generation'))
 INTO safe FROM public.operations op JOIN public.execution_attempts a ON a.id=(info->>'attempt')::uuid WHERE op.id=(info->>'operation')::uuid;
 IF NOT coalesce(safe,false) THEN SELECT EXISTS(SELECT 1 FROM d4.absence_seals s JOIN public.operations o ON o.id=s.operation_id WHERE s.delivery_id=delivery AND s.attempt_id=(info->>'attempt')::uuid AND o.state='RETRY_PENDING' AND o.lease_generation=s.generation AND NOT EXISTS(SELECT 1 FROM public.operation_leases WHERE operation_id=o.id) AND d4.absence_settled(s.id)) INTO safe;END IF;
 RETURN jsonb_build_object('schema','d4.worker.execution-status.v1','delivery_id',delivery,'operation',info->'operation',
  'attempt',info->'attempt','worker',info->'worker','resource',info->'resource','generation',info->'generation',
  'state',info->'state','retirable',coalesce(safe,false));
END $$;

CREATE OR REPLACE FUNCTION d4.absence_status(pid uuid,delivery uuid,cid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,d4 AS $$
DECLARE p d4.recovery_proofs;c d4.checkpoint_commands;
BEGIN
 SELECT * INTO p FROM d4.recovery_proofs WHERE id=pid;IF NOT FOUND THEN RETURN 'null'::jsonb;END IF;
 IF p.delivery_id IS DISTINCT FROM delivery OR p.proof->>'schema' IS DISTINCT FROM 'd4.absence.proof.v1' THEN RAISE EXCEPTION 'Recovery ownership conflict' USING ERRCODE='23514';END IF;
 SELECT * INTO c FROM d4.checkpoint_commands WHERE id=cid;
 IF FOUND THEN IF c.request->>'action' IS DISTINCT FROM 'ABSENCE_SETTLE' OR c.request->>'proof' IS DISTINCT FROM pid::text THEN RAISE EXCEPTION 'Recovery command conflict' USING ERRCODE='23514';END IF;RETURN c.response;END IF;
 RETURN jsonb_build_object('pending',true,'expected_version',p.proof->'row_version');
END $$;

REVOKE ALL ON ALL TABLES IN SCHEMA d4 FROM PUBLIC;
DO $$ DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure n FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace WHERE ns.nspname='d4' AND (p.proname LIKE 'absence_%' OR p.proname IN ('parent_linked','continuation_safe')) LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.n);END LOOP;END $$;
